package pl.zagranietyper.service;import pl.zagranietyper.model.*;import java.math.BigDecimal;
public final class FootballTeamStatisticComparisonSettlementEngine {public Result settle(FootballTeamStatisticComparisonCondition c,FootballFixtureStatisticsSnapshot s){var selected=s.value(c.selectedSide(),c.statisticType());var other=s.value(c.selectedSide()==FootballFixtureStatisticsSnapshot.TeamSide.HOME?FootballFixtureStatisticsSnapshot.TeamSide.AWAY:FootballFixtureStatisticsSnapshot.TeamSide.HOME,c.statisticType());if(s.status()!=FootballFixtureStatisticsSnapshot.FetchStatus.COMPLETE||selected.isEmpty()||other.isEmpty()||selected.get().status()!=FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN||other.get().status()!=FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN)return new Result(SettlementDecision.UNSUPPORTED,null,null);BigDecimal a=selected.get().value(),b=other.get().value();int cmp=a.compareTo(b);if(cmp==0)return new Result(SettlementDecision.UNSUPPORTED,a,b);boolean wins=c.relation()==FootballTeamStatisticComparisonCondition.Relation.MORE_THAN_OPPONENT?cmp>0:cmp<0;return new Result(wins?SettlementDecision.W:SettlementDecision.L,a,b);}public record Result(SettlementDecision decision,BigDecimal selectedValue,BigDecimal opponentValue){}}
